const input = $json.body || $json;
const id = Number(input.cursoId);
if (!id || !input.accion) throw new Error('cursoId y accion son obligatorios');
if (input.accion === 'ELIMINAR') {
  const r = await fetch('http://qdrant:6333/collections/cursos_academicos/points/delete?wait=true', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({points:[id]})});
  if (!r.ok) throw new Error('Qdrant no pudo borrar el vector');
  return [{json:{ok:true, accion:'ELIMINAR', cursoId:id}}];
}
const c = input.curso;
if (!c) throw new Error('Faltan datos del curso');
const texto = `Curso: ${c.nombre}. Categoría: ${c.categoria}. Nivel: ${c.nivel}. Duración: ${c.duracionHoras} horas. Prerrequisitos: ${c.prerrequisitos || 'Ninguno'}. Descripción: ${c.descripcion}`;
const emb = await fetch('https://openrouter.ai/api/v1/embeddings', {method:'POST', headers:{'Content-Type':'application/json','Authorization':`Bearer ${$env.OPENROUTER_API_KEY}`}, body:JSON.stringify({model:$env.OPENROUTER_EMBEDDING_MODEL || 'openai/text-embedding-3-small', input:texto})});
if (!emb.ok) throw new Error('No fue posible generar el embedding');
const vector = (await emb.json()).data?.[0]?.embedding;
const q = await fetch('http://qdrant:6333/collections/cursos_academicos/points?wait=true', {method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify({points:[{id,vector,payload:{curso_id:id,nombre:c.nombre,descripcion:c.descripcion,categoria:c.categoria,nivel:c.nivel,duracion_horas:c.duracionHoras,prerrequisitos:c.prerrequisitos || '',activo:true}}]})});
if (!q.ok) throw new Error('Qdrant no pudo indexar el curso');
return [{json:{ok:true, accion:'UPSERT', cursoId:id}}];
